export type Country = (typeof Country)[keyof typeof Country];

/** An `Identity` (an input struct). */
export interface Identity {
  document: Text;
  born: Day;
  nationality: Country;
  netWorth: U64;
  expires: Day;
  salt: Field | bigint | number | string;
}

/** A `Policy` (an input struct). */
export interface Policy {
  today: Day;
  bornBy: Day;
  minNetWorth: U64;
  /** A set of `Country`: one, or a list of them. */
  allowed: Country | readonly Country[];
}

/** Every input of `zk_kyc`. */
export interface ZkKycInputs {
  id: Identity;
  commitment: Field | bigint | number | string;
  policy: Policy;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface ZkKycPublicInputs {
  commitment: Field | bigint | number | string;
  policy: Policy;
}

/** A `Policy`, decoded, with its Rust methods. */
export class PolicyValue {
  today: Day;
  bornBy: Day;
  minNetWorth: bigint;
  allowed: Country[];

  constructor(v: {
    today: Day;
    bornBy: Day;
    minNetWorth: bigint;
    allowed: Country[];
  }) {
    this.today = v.today;
    this.bornBy = v.bornBy;
    this.minNetWorth = v.minNetWorth;
    this.allowed = v.allowed;
  }

  /**
   * At least `years` old on `today`.
   */
  minAge(years: U16): PolicyValue {
    return Policy.minAge(this, years);
  }

  /**
   * A national of one of `allowed` (a country, or a list of them).
   */
  nationalities(allowed: Country | readonly Country[]): PolicyValue {
    return Policy.nationalities(this, allowed);
  }

  /**
   * Worth at least `amount`, in the attestor's unit.
   */
  worthAtLeast(amount: U64): PolicyValue {
    return Policy.worthAtLeast(this, amount);
  }
}

/** The public inputs, decoded from a proof. */
export interface ZkKycPublicValues {
  commitment: Field;
  policy: PolicyValue;
}

/** The input structs, by name: what `fields` takes. */
export interface ZkKycStructs {
  Identity: Identity;
  Policy: Policy;
}

/**
 * `zk_kyc`: make a prover or verifier from a URL serving a copy of
 * `target/xark/zk_kyc/` (relative to the page in a browser) or from the bytes:
 *
 * ```ts
 * const prover = await ZkKyc.prover("/circuits/zk_kyc/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes());
 * const verifier = await ZkKyc.verifier(vkBytes);
 * verifier.verify(proof.toBytes()); // true
 * ```
 */
export const ZkKyc = new Circuit<ZkKycInputs, ZkKycPublicInputs, ZkKycPublicValues, ZkKycStructs>({
  name: "zk_kyc",
  schema,
  decodePublic,
  client: true,
});

export type ZkKycProver = Prover<ZkKycInputs, ZkKycPublicInputs, ZkKycPublicValues, ZkKycStructs>;
export type ZkKycVerifier = Verifier<ZkKycPublicInputs, ZkKycPublicValues, ZkKycStructs>;
export type ZkKycProof = Proof<ZkKycPublicValues>;

/** `Policy`'s Rust functions (`#[input] impl Policy`), run from `client.wasm`. */
export const Policy = {
  /**
   * A check on `today` that any holder with a valid document passes: tighten it
   * with the other constructors.
   */
  on(today: Day): PolicyValue {
    return decodePolicy(ZkKyc.call<Json<PolicyValue>>("Policy.on", [today]));
  },
  /**
   * At least `years` old on `today`.
   */
  minAge(policy: Policy, years: U16): PolicyValue {
    return decodePolicy(ZkKyc.call<Json<PolicyValue>>("Policy.min_age", [policy, years]));
  },
  /**
   * A national of one of `allowed` (a country, or a list of them).
   */
  nationalities(policy: Policy, allowed: Country | readonly Country[]): PolicyValue {
    return decodePolicy(ZkKyc.call<Json<PolicyValue>>("Policy.nationalities", [policy, allowed]));
  },
  /**
   * Worth at least `amount`, in the attestor's unit.
   */
  worthAtLeast(policy: Policy, amount: U64): PolicyValue {
    return decodePolicy(ZkKyc.call<Json<PolicyValue>>("Policy.worth_at_least", [policy, amount]));
  },
};

/** `Identity`'s Rust functions (`#[input] impl Identity`), run from `client.wasm`. */
export const Identity = {
  /**
   * The issuer's commitment: Poseidon2 over every field, so adding one extends it.
   */
  commitment(identity: Identity): Field {
    return new Field(ZkKyc.call<Json<Field>>("Identity.commitment", [identity]));
  },
};

function decodePublic(v: Json<ZkKycPublicValues>): ZkKycPublicValues {
  return {
    commitment: new Field(v.commitment),
    policy: decodePolicy(v.policy),
  };
}

function decodePolicy(v: Json<PolicyValue>): PolicyValue {
  return new PolicyValue({
    today: new Date(v.today),
    bornBy: new Date(v.bornBy),
    minNetWorth: BigInt(v.minNetWorth),
    allowed: v.allowed,
  });
}
